-- Necromancer (class 10) remaining spellbook batch (design A.6-A.9,
-- 2026-10-19): Bloodlet, Dark Command, Terror, Ghoul Armor, Embalm,
-- Lobotomize, Outbreak, Rule Undead, Unholy Shield, Lich Armor and
-- Dark Punishment, plus the three-tab spellbook split (A87: skill lines
-- 700 Reanimation / 701 Blood / 702 Plague).  Trainer learn spells
-- 61132-61142 and npc_trainer rows are generated by generate_trainers.py.
-- Generated by tools/generate_remaining_spells.py; re-runnable.

DELETE FROM `spell_template` WHERE `entry` BETWEEN 61076 AND 61086;
DELETE FROM `skill_line_ability` WHERE `id` BETWEEN 7318 AND 7328 OR `spell_id` BETWEEN 61076 AND 61086;

-- Bone Armor joins the exclusive armor line (A87 batch)
UPDATE `spell_template` SET `script_name` = 'spell_necromancer_armor' WHERE `entry` = 61015;

